// Phone remote, see remote.h.
//   GET /            control page (remote.html, embedded at build time)
//   GET /state       JSON published by the main loop
//   GET /set?k=v&..  numeric commands, queued for the main loop
#include "remote.h"
#include "remote_html.h"   // generated by CMake: REMOTE_HTML[]
#include "raylib.h"        // TraceLog
#include <arpa/inet.h>
#include <ifaddrs.h>
#include <net/if.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
#define QN 512
static RemoteCmd queue[QN];
static int qn;
static char *state;
static int port;

int RemotePoll(RemoteCmd *out, int max)
{
    pthread_mutex_lock(&mu);
    int n = qn < max ? qn : max;
    memcpy(out, queue, sizeof *out*n);
    memmove(queue, queue + n, sizeof *queue*(qn - n));
    qn -= n;
    pthread_mutex_unlock(&mu);
    return n;
}

void RemoteSetState(const char *json)
{
    char *s = strdup(json);
    pthread_mutex_lock(&mu);
    free(state); state = s;
    pthread_mutex_unlock(&mu);
}

// ------------------------------------------------------------- http
static void Send(int fd, const char *buf, size_t n)
{
    while (n > 0) {
        ssize_t k = send(fd, buf, n, MSG_NOSIGNAL);
        if (k <= 0) return;
        buf += k; n -= (size_t)k;
    }
}

static void Reply(int fd, const char *status, const char *type, const char *body, size_t n)
{
    char h[256];
    int hn = snprintf(h, sizeof h, "HTTP/1.1 %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nCache-Control: no-store\r\n"
                      "Access-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", status, type, n);
    Send(fd, h, (size_t)hn);
    Send(fd, body, n);
}

static void Push(const char *key, float v)
{
    pthread_mutex_lock(&mu);
    if (qn == QN) { memmove(queue, queue + 1, sizeof *queue*(QN - 1)); qn--; }   // full: drop the oldest
    snprintf(queue[qn].key, sizeof queue[qn].key, "%s", key);
    queue[qn].val = v;
    qn++;
    pthread_mutex_unlock(&mu);
}

static void Handle(int fd)
{
    struct timeval tv = { 2, 0 };
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    char req[4096]; int n = 0;
    while (n < (int)sizeof req - 1) {
        ssize_t k = recv(fd, req + n, sizeof req - 1 - n, 0);
        if (k <= 0) break;
        n += (int)k; req[n] = 0;
        if (strstr(req, "\r\n\r\n")) break;
    }
    req[n] = 0;
    char method[8], path[2048];
    if (sscanf(req, "%7s %2047s", method, path) != 2) return;
    if (!strcmp(path, "/") || !strncmp(path, "/?", 2) || !strcmp(path, "/index.html")) {
        Reply(fd, "200 OK", "text/html; charset=utf-8", (const char *)REMOTE_HTML, sizeof REMOTE_HTML - 1);
    } else if (!strcmp(path, "/state")) {
        pthread_mutex_lock(&mu);
        char *s = strdup(state ? state : "{}");
        pthread_mutex_unlock(&mu);
        Reply(fd, "200 OK", "application/json", s, strlen(s));
        free(s);
    } else if (!strncmp(path, "/set?", 5)) {
        // keys are [a-z0-9_], values plain numbers: no URL decoding needed
        for (char *tok = strtok(path + 5, "&"); tok; tok = strtok(NULL, "&")) {
            char *eq = strchr(tok, '=');
            if (!eq) continue;
            *eq = 0;
            Push(tok, (float)atof(eq + 1));
        }
        Reply(fd, "200 OK", "text/plain", "ok", 2);
    } else {
        Reply(fd, "404 Not Found", "text/plain", "not found", 9);
    }
}

// ------------------------------------------------------------- addresses, QR, beacon
static int Skip(const char *name)   // container bridges and the like: not reachable from the phone
{
    static const char *P[] = { "docker", "br-", "veth", "virbr", "vboxnet", "vmnet", "podman", "cni", "flannel", "lxc" };
    for (unsigned i = 0; i < sizeof P/sizeof P[0]; i++) if (!strncmp(name, P[i], strlen(P[i]))) return 1;
    return 0;
}

// LAN addresses, Wi-Fi first; also collects the broadcast addresses for the beacon
static int Addrs(char ips[][INET_ADDRSTRLEN], struct in_addr *bcast, int max)
{
    struct ifaddrs *ifs, *a;
    if (getifaddrs(&ifs) != 0) return 0;
    int n = 0;
    for (int pass = 0; pass < 2; pass++)
        for (a = ifs; a && n < max; a = a->ifa_next) {
            if (!a->ifa_addr || a->ifa_addr->sa_family != AF_INET) continue;
            if ((a->ifa_flags & IFF_LOOPBACK) || !(a->ifa_flags & IFF_UP) || Skip(a->ifa_name)) continue;
            int wifi = a->ifa_name[0] == 'w';
            if (wifi != (pass == 0)) continue;
            inet_ntop(AF_INET, &((struct sockaddr_in *)a->ifa_addr)->sin_addr, ips[n], INET_ADDRSTRLEN);
            bcast[n].s_addr = (a->ifa_flags & IFF_BROADCAST) && a->ifa_broadaddr
                ? ((struct sockaddr_in *)a->ifa_broadaddr)->sin_addr.s_addr : INADDR_BROADCAST;
            n++;
        }
    freeifaddrs(ifs);
    return n;
}

static void PrintAddress(char ips[][INET_ADDRSTRLEN], int n)
{
    if (n == 0) { printf("\nREMOTE: no network yet (port %d), waiting for Wi-Fi...\n\n", port); fflush(stdout); return; }
    char url[64];
    snprintf(url, sizeof url, "http://%s:%d/", ips[0], port);
    printf("\n==== REMOTE: phone control ====\n");
#ifdef QRENCODE_BIN
    fflush(stdout);
    char cmd[512];
    snprintf(cmd, sizeof cmd, "'%s' -t ANSIUTF8 -m 2 '%s'", QRENCODE_BIN, url);
    if (system(cmd) != 0) printf("(qrencode failed)\n");
#endif
    for (int i = 0; i < n; i++) printf("  http://%s:%d/\n", ips[i], port);
    printf("The Overtone Remote app finds this computer by itself; the QR opens the same page in a browser.\n\n");
    fflush(stdout);
}

static void *Conn(void *arg)
{
    int fd = (int)(long)arg;
    Handle(fd);
    close(fd);
    return NULL;
}

static void *Thread(void *arg)
{
    int ls = (int)(long)arg;
    int us = socket(AF_INET, SOCK_DGRAM, 0), one = 1;
    setsockopt(us, SOL_SOCKET, SO_BROADCAST, &one, sizeof one);
    char host[64] = "linux";
    gethostname(host, sizeof host - 1);
    char shown[8][INET_ADDRSTRLEN] = { { 0 } }; int nShown = -1;
    double nextBeacon = 0;
    for (;;) {
        struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
        double now = ts.tv_sec + ts.tv_nsec*1e-9;
        if (now >= nextBeacon) {
            nextBeacon = now + 1.0;
            char ips[8][INET_ADDRSTRLEN]; struct in_addr bc[8];
            int n = Addrs(ips, bc, 8);
            // address list changed (Wi-Fi joined, hotspot switched): print the QR again
            int changed = n != nShown;
            for (int i = 0; !changed && i < n; i++) changed = strcmp(ips[i], shown[i]) != 0;
            if (changed) { memcpy(shown, ips, sizeof shown); nShown = n; PrintAddress(ips, n); }
            char msg[128];
            int mn = snprintf(msg, sizeof msg, "OVERTONE %d %s", port, host);
            for (int i = 0; i <= n; i++) {   // every interface's broadcast + the global one
                struct sockaddr_in to = { .sin_family = AF_INET, .sin_port = htons(REMOTE_BEACON) };
                to.sin_addr.s_addr = i < n ? bc[i].s_addr : INADDR_BROADCAST;
                sendto(us, msg, (size_t)mn, 0, (struct sockaddr *)&to, sizeof to);
            }
        }
        fd_set fs; FD_ZERO(&fs); FD_SET(ls, &fs);
        struct timeval tv = { 0, 250000 };
        if (select(ls + 1, &fs, NULL, NULL, &tv) <= 0) continue;
        int fd = accept(ls, NULL, NULL);
        if (fd < 0) continue;
        // a thread per connection: browsers open idle spare connections that would block a serial loop
        pthread_t t;
        if (pthread_create(&t, NULL, Conn, (void *)(long)fd) == 0) pthread_detach(t);
        else close(fd);
    }
    return NULL;
}

void RemoteStart(int want)
{
    int ls = socket(AF_INET, SOCK_STREAM, 0), one = 1;
    setsockopt(ls, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
    for (port = want; port < want + 10; port++) {
        struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons((unsigned short)port), .sin_addr.s_addr = INADDR_ANY };
        if (bind(ls, (struct sockaddr *)&a, sizeof a) == 0) break;
    }
    if (port == want + 10 || listen(ls, 16) != 0) { TraceLog(LOG_WARNING, "REMOTE: no free port near %d", want); close(ls); return; }
    pthread_t t;
    pthread_create(&t, NULL, Thread, (void *)(long)ls);
    pthread_detach(t);
    TraceLog(LOG_INFO, "REMOTE: listening on port %d", port);
}
